#include <noarr/traversers.hpp>
#include <noarr/structures/interop/serialize_data.hpp>

#include "defines.hpp"
#include "bicg.hpp"

using num_t = DATA_TYPE;

namespace {

constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

struct tuning {
	// A: i x j (row-major: j is the inner/fast dimension)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);

	// 1D vectors
	DEFINE_PROTO_STRUCT(s_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(q_layout, i_vec); // length N, index 'i'
	DEFINE_PROTO_STRUCT(p_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(r_layout, i_vec); // length N, index 'i'
} tuning;

// Array initialization
// A: i x j
// r: i
// p: j
void init_array(auto A, auto r, auto p) {
	using namespace noarr;

	// Precompute lengths once; they are used repeatedly below
	const std::size_t m = p | get_length<'j'>(); // length in 'j'
	const std::size_t n = r | get_length<'i'>(); // length in 'i'

	// Precompute reciprocals to replace division by a constant and to
	// avoid the unnecessary modular operations from the original code:
	//   p[j] = (j % m) / m;  with 0 <= j < m  ==> j % m == j
	//   r[i] = (i % n) / n;  with 0 <= i < n  ==> i % n == i
	const num_t inv_m = num_t(1) / num_t(m);
	const num_t inv_n = num_t(1) / num_t(n);

	// p[j] = j / m;
	traverser(p).for_each([&](auto state) {
		const std::size_t j = get_index<'j'>(state);
		p[state] = num_t(j) * inv_m;
	});

	// r[i] = i / n;
	traverser(r).for_each([&](auto state) {
		const std::size_t i = get_index<'i'>(state);
		r[state] = num_t(i) * inv_n;
	});

	// A[i][j] = (i * (j + 1) % n) / n;
	// Here the modulus cannot be removed, but we still reuse inv_n.
	traverser(A).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		const auto value = (i * (j + 1)) % n;
		A[state] = num_t(value) * inv_n;
	});
}

// Main computational kernel
// A: i x j
// s: j
// q: i
// p: j
// r: i
//
// The original algorithm is:
//
//   s[j] = 0                           for all j
//   for i:
//     q[i] = 0
//     for j:
//       s[j] += r[i] * A[i][j]
//       q[i] += A[i][j] * p[j]
//
// Optimizations applied:
//   * Hoist r[i] out of the inner j-loop so it is loaded once per row.
//   * Accumulate q[i] into a scalar q_i and store it once per i.
//     This reduces both loads and stores for q[i].
//   * Keep the traversal order i (outer) / j (inner), which matches
//     the row‑major layout of A (j is the fast dimension).
[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	#pragma scop
	// s[j] = 0 for all j
	traverser(s).for_each([&](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// Multi-structure traverser so that all arrays share the same
	// index state; 'i' is the outer dimension, 'j' the inner one.
	auto trav = traverser(A, s, q, p, r);

	// For each i:
	trav.template for_dims<'i'>([&](auto inner) {
		// State with current i fixed
		auto istate = inner.state(); // contains only 'i'

		// Load r[i] once and keep in a register
		const num_t r_i = r[istate];

		// Accumulator for q[i], kept in a register to minimize
		// traffic to q's memory.
		num_t q_i = SCALAR_VAL(0.0);

		// Inner loop over j, visiting A row by row.
		inner.for_each([&](auto state) {
			// state has both 'i' and 'j'
			const num_t a_ij = A[state];
			const num_t p_j  = p[state];

			// s[j] += r[i] * A[i][j];
			// Even though s is indexed only by 'j', we use the
			// full state; s ignores the 'i' component.
			s[state] += r_i * a_ij;

			// q[i] += A[i][j] * p[j];
			q_i += a_ij * p_j;
		});

		// Finalize q[i] with a single store.
		q[istate] = q_i;
	});
	#pragma endscop
}

} // namespace

