// Array initialization
// A: i x j
// r: i
// p: j
void init_array(auto A, auto r, auto p) {
	using namespace noarr;

	// Precompute lengths and their reciprocals once to avoid repeated queries
	const std::size_t m = p | get_length<'j'>();
	const std::size_t n = r | get_length<'i'>();

	const num_t inv_m = SCALAR_VAL(1.0) / static_cast<num_t>(m);
	const num_t inv_n = SCALAR_VAL(1.0) / static_cast<num_t>(n);

	// p[j] = (j % m) / m;              (here j is always in [0, m), so j % m == j)
	traverser(p).for_each([&](auto state) {
		const std::size_t j = get_index<'j'>(state);
		p[state] = static_cast<num_t>(j) * inv_m;
	});

	// r[i] = (i % n) / n;              (here i is always in [0, n), so i % n == i)
	traverser(r).for_each([&](auto state) {
		const std::size_t i = get_index<'i'>(state);
		r[state] = static_cast<num_t>(i) * inv_n;
	});

	// A[i][j] = (i * (j + 1) % n) / n;
	// We keep the modulo because (j + 1) can exceed n.
	traverser(A).for_each([&](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		const std::size_t val = (i * (j + 1)) % n;
		A[state] = static_cast<num_t>(val) * inv_n;
	});
}

// Main computational kernel
// A: i x j
// s: j
// q: i
// p: j
// r: i
//
// Mathematically:
//   q[i] = sum_j A[i][j] * p[j]
//   s[j] = sum_i r[i] * A[i][j]
//
// The original fused version performs both accumulations in a single
// nested loop. Here we retain the same per-element accumulation order
// for each of q and s, but split the computation into two logically
// simpler parts:
//   1) q = A * p  (parallel over i, no cross-row dependencies)
//   2) s = A^T * r (sequential, using the same traversal order as the
//      original fused kernel for s).
//
// For each i, we keep r[i] and q[i] in registers to reduce memory
// traffic.  All loop nests are expressed via Noarr traversers.
