void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	#pragma scop

	// ------------------------------------------------------------------
	// 1) Initialize s[j] = 0 for all j
	//    q[i] will be explicitly written in the q-phase, so we do not
	//    need to clear it beforehand.
	// ------------------------------------------------------------------
	traverser(s).for_each([&](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// ------------------------------------------------------------------
	// 2) q = A * p   -- parallel over rows ('i' dimension)
	//
	// For each i:
	//   q[i] = sum_j A[i][j] * p[j];
	//
	// There are no cross-row dependencies: each iteration writes to a
	// distinct q[i] and only reads from A and p, so we can safely use
	// OpenMP parallelization on the outer 'i' dimension.
	// ------------------------------------------------------------------
	{
		auto trav_q = traverser(A, q, p);

		// The range-based loop iterates the top-most dimension of the
		// joint structure, which is 'i' with our layout.
		#pragma omp parallel for schedule(static)
		for (auto trav_i : trav_q) {
			// trav_i is a traverser with the current 'i' fixed;
			// it will iterate over the remaining 'j' dimension.
			auto istate = trav_i.state();

			// Accumulator for q[i], kept in a register.
			num_t qi = SCALAR_VAL(0.0);

			trav_i.for_each([&](auto state) {
				// state has both 'i' and 'j'; indexing A and p with it
				// is safe – bags ignore superfluous dimensions.
				const num_t a_ij = A[state];
				const num_t p_j  = p[state];
				qi += a_ij * p_j;
			});

			// Store the final result for this row.
			q[istate] = qi;
		}
	}

	// ------------------------------------------------------------------
	// 3) s = A^T * r   -- sequential over i, j
	//
	// For each i:
	//   for each j:
	//     s[j] += r[i] * A[i][j];
	//
	// This uses the same (i-outer, j-inner) traversal order as the
	// original fused kernel for the updates to s, so the accumulation
	// order per s[j] is preserved.  We also hoist r[i] outside the
	// inner loop to keep it in a register.
	// ------------------------------------------------------------------
	traverser(A, s, r).template for_dims<'i'>([&](auto inner) {
		// State with current i fixed
		auto istate = inner.state();

		// Cache r[i] in a register
		const num_t r_i = r[istate];

		// Loop over j for this fixed i
		inner.for_each([&](auto state) {
			// state has 'i' and 'j'
			const num_t a_ij = A[state];

			// s[j] += r[i] * A[i][j];
			s[state] += r_i * a_ij;
		});
	});

	#pragma endscop
}

