using num_t = DATA_TYPE;

namespace {

// Common 1D layout proto-structures
constexpr auto i_vec = noarr::vector<'i'>();
constexpr auto j_vec = noarr::vector<'j'>();

// Tunable blocking factor for the inner 'j' (column) dimension.
// This controls the width of the tiles processed at once.
//  - Larger values increase temporal locality for q[i] and r[i],
//    but may increase cache pressure for s[j], p[j].
//  - Must be > 0. 64 is a reasonable default for modern CPUs.
constexpr std::size_t BICG_J_BLOCK = 64;

struct tuning {
	// A: i x j (row-major: j is the inner/fast dimension)
	// scalar<num_t> ^ j_vec ^ i_vec => dims: 'i' (outer), 'j' (inner)
	DEFINE_PROTO_STRUCT(a_layout, j_vec ^ i_vec);

	// 1D vectors
	DEFINE_PROTO_STRUCT(s_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(q_layout, i_vec); // length N, index 'i'
	DEFINE_PROTO_STRUCT(p_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(r_layout, i_vec); // length N, index 'i'
} tuning;

// ---------------------------------------------------------------------------
// Array initialization
// A: i x j
// r: i
// p: j
// ---------------------------------------------------------------------------
void init_array(auto A, auto r, auto p) {
	using namespace noarr;

	// Precompute lengths once (cheaper than querying inside each element)
	const std::size_t m = p | get_length<'j'>();
	const std::size_t n = r | get_length<'i'>();

	// p[j] = (j % m) / m;
	traverser(p).for_each([=](auto state) {
		const std::size_t j = get_index<'j'>(state);
		p[state] = (num_t)(j % m) / (num_t)m;
	});

	// r[i] = (i % n) / n;
	traverser(r).for_each([=](auto state) {
		const std::size_t i = get_index<'i'>(state);
		r[state] = (num_t)(i % n) / (num_t)n;
	});

	// A[i][j] = (i * (j + 1) % n) / n;
	const std::size_t nA = A | get_length<'i'>();
	traverser(A).for_each([=](auto state) {
		auto [i, j] = get_indices<'i', 'j'>(state);
		A[state] = (num_t)(i * (j + 1) % nA) / (num_t)nA;
	});
}

// ---------------------------------------------------------------------------
// Main computational kernel
// Original math:
//   For all j: s[j] = 0
//   For all i:
//     q[i] = 0
//     For all j:
//       s[j] += r[i] * A[i][j];
//       q[i] += A[i][j] * p[j];
//
// Optimized version:
//   - Still computes identical results (same summation order per index).
//   - Zero-initializes s and q in dedicated passes (avoids re-zeroing q[i]
//     if we use multiple sweeps over j).
//   - Tiles the inner j-dimension into blocks of BICG_J_BLOCK columns
//     using noarr::into_blocks for improved cache locality.
//     * Inside each i-row, we traverse j-blocks ('J') and then elements
//       within the block ('j'), keeping r[i] and q[i] in registers.
//   - Handles the "tail" columns (if M is not divisible by BICG_J_BLOCK)
//     as a separate slice without blocking.
// ---------------------------------------------------------------------------
[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	#pragma scop

	const std::size_t m = s | get_length<'j'>(); // number of columns
	const std::size_t n = q | get_length<'i'>(); // number of rows

	// Guard trivial cases early
	if (m == 0 || n == 0)
		return;

	// ----------------------------------------------------------------------
	// 1) Zero-initialize s and q once
	// ----------------------------------------------------------------------

	// s[j] = 0 for all j
	traverser(s).for_each([=](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// q[i] = 0 for all i
	traverser(q).for_each([=](auto state) {
		q[state] = SCALAR_VAL(0.0);
	});

	// ----------------------------------------------------------------------
	// 2) Main j-range processed in tiles of width BICG_J_BLOCK
	//    We slice [0, main_m) where main_m is the largest multiple of
	//    BICG_J_BLOCK not exceeding m. This allows us to use
	//    into_blocks<'j','J','j'> with a static minor block size.
	// ----------------------------------------------------------------------

	const std::size_t main_m = (m / BICG_J_BLOCK) * BICG_J_BLOCK;

	if (main_m > 0) {
		// Slice view for the "main" fully-tiled column range [0, main_m)
		auto slice_main = slice<'j'>(0, main_m);
		auto A_main = A ^ slice_main;
		auto s_main = s ^ slice_main;
		auto p_main = p ^ slice_main;

		// Tiled traverser:
		//   - original 'j' is split into 'J' (block index) and 'j' (index
		//     within block) with block size BICG_J_BLOCK
		//   - dimensions: 'i', 'J', 'j'
		auto trav_main =
			traverser(A_main, s_main, q, p_main, r)
			.order(into_blocks<'j', 'J', 'j'>(noarr::lit<BICG_J_BLOCK>));

		// Outer loop over rows 'i'
		trav_main.template for_dims<'i'>([=](auto trav_i) {
			// State with current i fixed (only 'i' is present here)
			auto istate = trav_i.state();

			// Keep row-specific values in registers:
			//   - r_i is reused for all columns j in this row
			//   - q_i accumulates q[i] for this row
			num_t r_i = r[istate];
			num_t q_i = q[istate]; // currently 0.0

			// For each j-block (dimension 'J') in this row
			trav_i.template for_dims<'J'>([&](auto trav_block) {
				// Now only the inner minor 'j' varies within this block
				trav_block.for_each([&](auto state) {
					// state has 'i', 'J', 'j'; bags that do not use a
					// particular dimension simply ignore it.
					const num_t a_ij = A_main[state];

					// s[j] += r[i] * A[i][j];
					s_main[state] += r_i * a_ij;

					// q[i] += A[i][j] * p[j];
					q_i += a_ij * p_main[state];
				});
			});

			// Store accumulated q[i] back to memory once per row
			q[istate] = q_i;
		});
	}

	// ----------------------------------------------------------------------
	// 3) Tail j-range [main_m, m) without blocking (if m not divisible
	//    by BICG_J_BLOCK). We treat it as a separate slice; q[i] is
	//    initialized from its current value (contributions from the
	//    main range) and further accumulated. This preserves the exact
	//    summation order over j for each (fixed) i.
	// ----------------------------------------------------------------------

	if (main_m < m) {
		const std::size_t tail_len = m - main_m;

		auto slice_tail = slice<'j'>(main_m, tail_len);
		auto A_tail = A ^ slice_tail;
		auto s_tail = s ^ slice_tail;
		auto p_tail = p ^ slice_tail;

		auto trav_tail = traverser(A_tail, s_tail, q, p_tail, r);

		// Outer loop over rows 'i'
		trav_tail.template for_dims<'i'>([=](auto trav_i) {
			auto istate = trav_i.state();

			num_t r_i = r[istate];
			// Start from existing q[i] (which contains contributions
			// from j in [0, main_m))
			num_t q_i = q[istate];

			// Simple inner loop over the remaining columns in this row
			trav_i.for_each([&](auto state) {
				const num_t a_ij = A_tail[state];

				s_tail[state] += r_i * a_ij;
				q_i          += a_ij * p_tail[state];
			});

			q[istate] = q_i;
		});
	}

	#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// Retrieve problem size
	std::size_t n = N; // length in 'i'
	std::size_t m = M; // length in 'j'

	// Common length proto-structure
	auto set_lengths =
		noarr::set_length<'i'>(n) ^
		noarr::set_length<'j'>(m);

	// Allocate bags with chosen layouts
	auto A = noarr::bag(noarr::scalar<num_t>() ^ tuning.a_layout ^ set_lengths);
	auto s = noarr::bag(noarr::scalar<num_t>() ^ tuning.s_layout ^ set_lengths);
	auto q = noarr::bag(noarr::scalar<num_t>() ^ tuning.q_layout ^ set_lengths);
	auto p = noarr::bag(noarr::scalar<num_t>() ^ tuning.p_layout ^ set_lengths);
	auto r = noarr::bag(noarr::scalar<num_t>() ^ tuning.r_layout ^ set_lengths);

	// Initialize arrays
	init_array(A.get_ref(), r.get_ref(), p.get_ref());

	auto start = std::chrono::high_resolution_clock::now();

	// Run kernel
	kernel_bicg(A.get_ref(), s.get_ref(), q.get_ref(), p.get_ref(), r.get_ref());

	auto end = std::chrono::high_resolution_clock::now();
	auto duration = std::chrono::duration<long double>(end - start);

	// Print live-out data to prevent dead-code elimination
	if (argc > 0 && argv[0] != ""s) {
		std::cerr << std::fixed << std::setprecision(2);
		noarr::serialize_data(std::cerr, s.get_ref());
		noarr::serialize_data(std::cerr, q.get_ref());
	}

	// Print timing
	std::cout << std::fixed << std::setprecision(6);
	std::cout << duration.count() << std::endl;

	return 0;
}
