	DEFINE_PROTO_STRUCT(q_layout, i_vec); // length N, index 'i'
	DEFINE_PROTO_STRUCT(p_layout, j_vec); // length M, index 'j'
	DEFINE_PROTO_STRUCT(r_layout, i_vec); // length N, index 'i'
} tuning;

// Array initialization
// A: i x j
// r: i
// p: j
//
// Optimizations vs original:
//  - Precompute lengths once instead of querying them in every iteration.
//  - Keep traversal order explicit (i outer, j inner) for A to match row-major layout.
//  - Capture bags by reference in lambdas to avoid copying them.
void init_array(auto A, auto r, auto p) {
	using namespace noarr;

	// Precompute lengths (constant for whole initialization)
	const std::size_t m = p | get_length<'j'>(); // length in 'j' (M)
	const std::size_t n = A | get_length<'i'>(); // length in 'i' (N)

	// p[j] = (j % m) / m;
	traverser(p).for_each([&](auto state) {
		const std::size_t j = get_index<'j'>(state);
		p[state] = static_cast<num_t>(j % m) / static_cast<num_t>(m);
	});

	// r[i] = (i % n) / n;
	traverser(r).for_each([&](auto state) {
		const std::size_t i = get_index<'i'>(state);
		r[state] = static_cast<num_t>(i % n) / static_cast<num_t>(n);
	});

	// A[i][j] = (i * (j + 1) % n) / n;
	// Traverse A with 'i' outer and 'j' inner to follow row-major layout
	traverser(A).template for_dims<'i'>([&](auto inner) {
		// state with current i fixed
		auto istate = inner.state();
		const std::size_t i = get_index<'i'>(istate);

		inner.for_each([&](auto state) {
			const std::size_t j = get_index<'j'>(state);
			A[state] = static_cast<num_t>((i * (j + 1)) % n) / static_cast<num_t>(n);
		});
	});
}

// Main computational kernel
// A: i x j
// s: j
// q: i
// p: j
// r: i
//
// Optimizations vs original:
//  - Still use noarr::traverser with for_dims<'i'> so the loop nest is clearly i-outer, j-inner.
//  - Zero s[j] once before the main loop (same as original).
//  - For each i, load r[i] once into a scalar r_i.
//  - Accumulate q[i] in a scalar q_i inside the inner j-loop and write it back once at the end.
//    This removes one load and one store of q[i] per j-iteration and improves vectorization.
//  - s[j] is still updated in-place; note that the state passed to s has both 'i' and 'j',
//    but the extra 'i' index is ignored by the 1D structure s (as per noarr semantics).
[[gnu::flatten, gnu::noinline]]
void kernel_bicg(auto A, auto s, auto q, auto p, auto r) {
	using namespace noarr;

	#pragma scop
	// s[j] = 0 for all j
	traverser(s).for_each([&](auto state) {
		s[state] = SCALAR_VAL(0.0);
	});

	// For each i:
	//   q[i] = 0;
	//   for each j:
	//     s[j] += r[i] * A[i][j];
	//     q[i] += A[i][j] * p[j];
	//
	// Implementation details:
	//  - We traverse all five bags together to keep indices consistent.
	//  - for_dims<'i'> makes 'i' the outer loop; inner.for_each then iterates 'j'.
	//  - r[i] is loaded once into r_i.
	//  - q[i] is accumulated in q_i and stored once after the inner loop.
	traverser(A, s, q, p, r).template for_dims<'i'>([&](auto inner) {
		// State with current i fixed; suitable to index r and q
		auto istate = inner.state();

		const num_t r_i = r[istate];       // cache r[i] for this row
		num_t       q_i = SCALAR_VAL(0.0); // accumulator for q[i]

		// loop over j
		inner.for_each([&](auto state) {
			// state has 'i' and 'j'
			const num_t A_ij = A[state];
			const num_t p_j  = p[state]; // p has only 'j'; extra 'i' in state is ignored

			// s[j] += r[i] * A[i][j];
			// s has only 'j'; extra 'i' from state is ignored by noarr
			s[state] += r_i * A_ij;

			// q[i] += A[i][j] * p[j]; accumulated in a register
			q_i += A_ij * p_j;
		});

		// Write q[i] once after finishing the row
		q[istate] = q_i;
	});
	#pragma endscop
}

